#!/usr/bin/env node
/**
 * Generator for `llms.txt` / `llms-full.txt` (AI search, llmstxt.org).
 *
 * The only source is `website/llms/<locale>.md`: one public product
 * description per website language, written for the web and reviewed like
 * any page text. Nothing else in the repository is read; internal notes
 * (glossary, audience, decisions) never reach a public file. A Vitest guard
 * (`__tests__/generate-llms-txt.test.ts`) holds that boundary.
 *
 * Outputs (committed, regenerated by every build):
 *   - `public/llms.txt` — English index after llmstxt.org: H1, blockquote,
 *     link lists, plus one link per language to its Markdown description.
 *   - `public/llms/<locale>.md` — the description of each language as is.
 *   - `public/llms-full.txt` — all descriptions in one file, English first.
 *
 * Delivery: llmstxt.org defines one `/llms.txt` at the site root, so the
 * index stays single and English (as the convention and most crawlers
 * expect) and points to the per-language Markdown files; `llms-full.txt`
 * carries every language so a single fetch covers the whole product.
 *
 * Run: `node scripts/generate-llms-txt.mjs` (part of `npm run build`).
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

// ---------------------------------------------------------------------------
// Pure helpers (testable in isolation)
// ---------------------------------------------------------------------------

/**
 * Baut die kuratierte `llms.txt` nach der llmstxt.org-Konvention. Format:
 *
 *   # <title>
 *
 *   > <description>
 *
 *   ## <section title>
 *
 *   - [<link text>](<url>): <optional description>
 *
 * Der Output ist deterministisch und enthält keinen Anti-Vokabular-Treffer
 * (siehe Issue 02 Brand-Vocabulary-Gate).
 *
 * @param {object} input
 * @param {string} input.title - Produkt-Name als H1.
 * @param {string} input.description - Ein-Satz-Beschreibung im Blockquote.
 * @param {ReadonlyArray<{ title: string, links: ReadonlyArray<{ label: string, url: string, note?: string }> }>} input.sections
 *   Sektionen mit ihren Linklisten in Output-Reihenfolge.
 * @returns {string} Vollständige llms.txt mit abschließendem Newline.
 */
export function buildLlmsTxt({ title, description, sections }) {
  const lines = [];
  lines.push(`# ${title}`);
  lines.push("");
  lines.push(`> ${description}`);
  for (const section of sections) {
    lines.push("");
    lines.push(`## ${section.title}`);
    lines.push("");
    for (const link of section.links) {
      const noteSuffix = link.note ? `: ${link.note}` : "";
      lines.push(`- [${link.label}](${link.url})${noteSuffix}`);
    }
  }
  lines.push("");
  return lines.join("\n");
}

/**
 * Builds `llms-full.txt`: every language's description in order, separated
 * by a rule, each opening with its own `# WhisPaste` heading.
 *
 * @param {ReadonlyArray<{ locale: string, markdown: string }>} descriptions
 * @returns {string} Complete llms-full.txt with a trailing newline.
 */
export function buildLlmsFullTxt(descriptions) {
  const parts = descriptions.map(({ locale, markdown }) => `<!-- lang: ${locale} -->\n\n${markdown.trim()}`);
  return `${parts.join("\n\n---\n\n")}\n`;
}

