/**
 * Kuratierte Description für `llms.txt`. Folgt PRD §D-Brand-Sprache: explizit
 * `voice-input tool`, MIT-Lizenz, drei Desktop-Plattformen.
 */
const LLMS_TXT_TITLE = "WhisPaste";
const LLMS_TXT_DESCRIPTION =
  "WhisPaste is an MIT-licensed voice-input tool for Windows, macOS, and Linux that transcribes speech locally and copies the transcript to the clipboard or, with Auto-Paste switched on, inserts it at the cursor position of the active application (on Linux through a virtual uinput keyboard). Two on-device engines are available: whisper.cpp (99 languages, GPU-accelerated) and Parakeet (~25 languages, GPU-accelerated on Metal, Vulkan or CUDA with a CPU fallback via sherpa-onnx; several times faster than the compact whisper.cpp model on the same CPU in our Apple M5 benchmark). It is a desktop-only app; iOS and Android are not planned.";

/**
 * Liefert die default-Section-Liste, die `main()` für den Production-Build
 * verwendet. Exportiert, damit Tests den exakten Builder-Aufruf reproduzieren
 * können, ohne die Section-Definition zu duplizieren.
 */
export function defaultLlmsTxtInput() {
  return {
    title: LLMS_TXT_TITLE,
    description: LLMS_TXT_DESCRIPTION,
    sections: LLMS_TXT_SECTIONS,
  };
}

// ---------------------------------------------------------------------------
// CLI entry point
// ---------------------------------------------------------------------------

/** Website languages, English first: the order of llms-full.txt and the index. */
export const LLMS_LOCALES = Object.freeze(["en", "de", "es", "pt", "it", "ru", "zh", "fr"]);

const WEBSITE_DIR = resolve(dirname(fileURLToPath(import.meta.url)), "..");

/** The one directory the generator reads from. */
export const LLMS_SOURCE_DIR = join(WEBSITE_DIR, "llms");

/** Source file of `locale`; the only paths the generator ever reads. */
export function llmsSourcePath(locale) {
  return join(LLMS_SOURCE_DIR, `${locale}.md`);
}

/** Index section with one Markdown description per language. */
export function languagesSection() {
  return {
    title: "Languages",
    links: LLMS_LOCALES.map((locale) => ({
      label: `WhisPaste (${locale})`,
      url: `https://whispaste.de/llms/${locale}.md`,
    })),
  };
}

/** Builds every output from the public sources: `{ relativePath: content }`. */
export async function buildOutputs() {
  const descriptions = await Promise.all(
    LLMS_LOCALES.map(async (locale) => ({
      locale,
      markdown: await readFile(llmsSourcePath(locale), "utf8"),
    })),
  );
  const input = defaultLlmsTxtInput();
  /** @type {Record<string, string>} */
  const outputs = {
    "llms.txt": buildLlmsTxt({ ...input, sections: [...input.sections, languagesSection()] }),
    "llms-full.txt": buildLlmsFullTxt(descriptions),
  };
  for (const { locale, markdown } of descriptions) {
    outputs[`llms/${locale}.md`] = `${markdown.trim()}\n`;
  }
  return outputs;
}

export async function main() {
  const outputs = await buildOutputs();
  const publicDir = join(WEBSITE_DIR, "public");
  await mkdir(join(publicDir, "llms"), { recursive: true });
  await Promise.all(
    Object.entries(outputs).map(([rel, content]) => writeFile(join(publicDir, rel), content, "utf8")),
  );
  process.stdout.write(`generate-llms-txt: wrote ${Object.keys(outputs).length} files to public/\n`);
}

// Only auto-run when invoked as a CLI (not when imported as a module).
const invokedAsCli = (() => {
  if (!process.argv[1]) return false;
  try {
    return pathToFileURL(process.argv[1]).href === import.meta.url;
  } catch {
    return false;
  }
})();

if (invokedAsCli) {
  main().catch((err) => {
    process.stderr.write(`generate-llms-txt: ${err.message ?? err}\n`);
    process.exit(1);
  });
}
